function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function referenceCard(title, input, output, explanation, extraStyle = '') {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
    *{box-sizing:border-box}body{margin:0;padding:24px;background:#090d16;color:#e5e7eb;font:15px/1.55 system-ui,sans-serif}
    main{max-width:620px;margin:auto;padding:24px;border:1px solid #334155;border-radius:14px;background:#111827}
    .eyebrow{color:#a78bfa;font:700 11px monospace;letter-spacing:.12em}h1{font-size:22px}code{color:#a7f3d0;overflow-wrap:anywhere}
    .result{padding:10px 12px;border-radius:8px;background:#052e2b;color:#a7f3d0}${extraStyle}</style></head><body><main>
    <p class="eyebrow">REFERENCE EXAMPLE · NOT A PROGRAM RUN</p><h1>${escapeHtml(title)}</h1>
    <p><strong>Input:</strong> <code>${escapeHtml(input)}</code></p><p class="result"><strong>Expected value:</strong> <code>${escapeHtml(output)}</code></p>
    <p>${escapeHtml(explanation)}</p></main></body></html>`;
}

function makeCodeLesson({ course, title, objective, description, input, output, instructions, hint, explanation, checks, starterCode, timeLimit = 300 }) {
  return {
    course,
    title,
    description,
    learningObjective: objective,
    instructions,
    workedExample: { input, output, explanation },
    hint,
    explanation,
    contentStatus: 'authored',
    assessmentMode: 'source-rubric',
    timeLimit,
    testCases: checks.map((check, index) => ({ id: index + 1, description: check })),
    expectedOutput: referenceCard(title, input, output, explanation),
    expectedOutputHint: `Reference example only — input: ${input}; expected value: ${output}. Submitted code is not executed in this mode.`,
    starterCode,
  };
}

function makeHtmlLesson({ title, objective, description, instructions, example, hint, explanation, checks, starterCode, expectedOutput, timeLimit = 240 }) {
  return {
    title,
    description,
    learningObjective: objective,
    instructions,
    workedExample: { ...example, explanation },
    hint,
    explanation,
    contentStatus: 'authored',
    assessmentMode: 'source-rubric',
    timeLimit,
    testCases: checks.map((check, index) => ({ id: index + 1, description: check })),
    expectedOutput,
    expectedOutputHint: 'Visual reference only. The HTML preview is rendered in a sandbox; completion is reviewed against source requirements, not browser-executed tests.',
    starterCode,
  };
}

function htmlPage(title, content) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title></head><body><main>${content}</main></body></html>`;
}

